select (select count(*) from movimiento) as movimientos, (select count(*) from bitacora) as bitacora, (select count(*) from usuario) as usuarios, (select cantidad from saldo where acopio_id='d0000000-0000-4000-8000-000000000013' and categoria_id='7db7c12a-b3e6-4a81-bf40-a3288cbdf2e3') as saldo_suba, (select count(*) from pg_trigger where not tgisinternal) as disparadores, (select count(*) from _prisma_migrations) as migraciones;
